let url = String($json['Website URL'] || '').trim();
if (!/^https?:\/\//i.test(url)) url = 'https://' + url;
const u = new URL(url);
return { json: {
  company: $json['Company'], website: u.href, origin: u.origin, contact_name: $json['Contact name'] || '',
  contact_email: $json['Contact email'] || '', goal: $json['Primary goal'], budget: Number($json['Monthly budget (USD)']) || 0,
  notes: $json['Discovery call notes'] || '', am_email: $json['Send proposal to (AM email)'],
} };

const stripHtml = (h) => String(h || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#39;|&apos;/g, "'").replace(/&quot;/g, '"')
  .replace(/\s+/g, ' ').trim();
const grab = (h, re) => { const m = String(h || '').match(re); return m ? stripHtml(m[1]).slice(0, 300) : ''; };
const grabAll = (h, re, n = 10) => [...String(h || '').matchAll(re)].map((m) => stripHtml(m[1])).filter(Boolean).slice(0, n);

const brief = $('Normalize Brief').item.json;
const home = $('Fetch Homepage').item.json;
const robots = $('Fetch robots.txt').item.json;
const sitemap = $('Fetch sitemap.xml').item.json;
const html = typeof home.html === 'string' ? home.html : (typeof home.body === 'string' ? home.body : '');
const ok = (r) => r && !r.error && (r.statusCode === undefined || r.statusCode < 400);
const bodyOf = (r) => String(r?.html ?? r?.body ?? '');
const attr = (re) => (html.match(re) || [])[1] || '';
const imgs = [...html.matchAll(/<img\b[^>]*>/gi)].map((m) => m[0]);
const links = [...html.matchAll(/<a\b[^>]*href=["']([^"'#]+)/gi)].map((m) => m[1]);
const host = new URL(brief.website).host;
const internal = links.filter((l) => l.startsWith('/') || l.includes(host)).length;
const text = stripHtml(html);
const title = grab(html, /<title[^>]*>([\s\S]*?)<\/title>/i);
const metaDesc = attr(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)/i);
const jsonLdTypes = [...html.matchAll(/"@type"\s*:\s*"([^"]+)"/g)].map((m) => m[1]);
const robotsTxt = bodyOf(robots);
const signals = {
  reachable: !!html, status_code: home.statusCode ?? null, https: brief.website.startsWith('https://'),
  title, title_length: title.length, meta_description: metaDesc, meta_description_length: metaDesc.length,
  h1: grabAll(html, /<h1[^>]*>([\s\S]*?)<\/h1>/gi, 5), h2: grabAll(html, /<h2[^>]*>([\s\S]*?)<\/h2>/gi, 12),
  canonical: attr(/<link[^>]+rel=["']canonical["'][^>]+href=["']([^"']*)/i),
  meta_robots: attr(/<meta[^>]+name=["']robots["'][^>]+content=["']([^"']*)/i),
  viewport: /<meta[^>]+name=["']viewport["']/i.test(html), html_lang: attr(/<html[^>]+lang=["']([^"']*)/i),
  og_title: /property=["']og:title["']/i.test(html), og_image: /property=["']og:image["']/i.test(html),
  structured_data_types: [...new Set(jsonLdTypes)].slice(0, 15),
  images: imgs.length, images_missing_alt: imgs.filter((t) => !/\balt=["'][^"']+["']/i.test(t)).length,
  internal_links: internal, external_links: links.length - internal, forms: (html.match(/<form\b/gi) || []).length,
  buttons_and_ctas: grabAll(html, /<(?:button|a)[^>]*class=["'][^"']*(?:btn|button|cta)[^"']*["'][^>]*>([\s\S]*?)<\/(?:button|a)>/gi, 12),
  word_count: text ? text.split(' ').length : 0, html_kb: Math.round(html.length / 1024),
  scripts: (html.match(/<script\b/gi) || []).length,
  robots_txt_found: ok(robots) && /user-agent/i.test(robotsTxt),
  robots_blocks_all: /user-agent:\s*\*\s*[\r\n]+\s*disallow:\s*\/\s*$/im.test(robotsTxt),
  sitemap_found: ok(sitemap) && /<(urlset|sitemapindex)/i.test(bodyOf(sitemap)),
  tracking: Object.entries({ 'GA4 (gtag)': /gtag\(|googletagmanager\.com\/gtag/, 'Google Tag Manager': /GTM-[A-Z0-9]+/, 'Meta Pixel': /connect\.facebook\.net|fbq\(/,
    'LinkedIn Insight': /snap\.licdn\.com/, 'Hotjar': /hotjar/i, 'Microsoft Clarity': /clarity\.ms/ }).filter(([, re]) => re.test(html)).map(([k]) => k),
};
const page_copy = text.slice(0, 6000);

const issue = { type: 'object', additionalProperties: false, required: ['issue', 'evidence', 'impact', 'fix'],
  properties: { issue: { type: 'string' }, evidence: { type: 'string' }, impact: { type: 'string', enum: ['high', 'medium', 'low'] }, fix: { type: 'string' } } };
const schema = { type: 'object', additionalProperties: false,
  required: ['seo_score', 'summary', 'critical_issues', 'quick_wins', 'opportunities'],
  properties: { seo_score: { type: 'integer', description: '0-100' }, summary: { type: 'string' },
    critical_issues: { type: 'array', items: issue }, quick_wins: { type: 'array', items: { type: 'string' } },
    opportunities: { type: 'array', items: { type: 'string' } } } };
return { json: { ...brief, signals, page_copy, brain: {
  skill: 'seo-audit', caller: 'Audit & Proposal', client: brief.company, effort: 'high', max_tokens: 12000, schema,
  context: { company: brief.company, url: brief.website, goal: brief.goal, technical_signals: signals, homepage_copy: page_copy },
  task: 'Run an SEO audit of this homepage using only the crawl signals and copy provided (you cannot fetch more pages). Score 0-100. List the most important issues, each with the exact evidence from the signals, its impact, and a concrete fix. Add quick wins that take under a day, and bigger opportunities. Say where a full crawl would be needed to confirm something.',
} } };

const x = $json;
const schema = { type: 'object', additionalProperties: false,
  required: ['cro_score', 'value_prop_assessment', 'friction_points', 'experiments'],
  properties: { cro_score: { type: 'integer', description: '0-100' }, value_prop_assessment: { type: 'string' },
    friction_points: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['issue', 'evidence', 'fix'],
      properties: { issue: { type: 'string' }, evidence: { type: 'string' }, fix: { type: 'string' } } } },
    experiments: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['hypothesis', 'change', 'primary_metric', 'expected_impact'],
      properties: { hypothesis: { type: 'string' }, change: { type: 'string' }, primary_metric: { type: 'string' }, expected_impact: { type: 'string', enum: ['high', 'medium', 'low'] } } } } } };
const { ai, ai_text, ai_error, ai_meta, ...rest } = x;
return { json: { ...rest, seo: ai || { seo_score: null, summary: ai_error, critical_issues: [], quick_wins: [], opportunities: [] }, brain: {
  skill: 'cro', caller: 'Audit & Proposal', client: x.company, effort: 'high', max_tokens: 10000, schema,
  context: { company: x.company, goal: x.goal, discovery_notes: x.notes, headings: { h1: x.signals.h1, h2: x.signals.h2 }, ctas: x.signals.buttons_and_ctas, forms: x.signals.forms, homepage_copy: x.page_copy },
  task: 'Review this homepage for conversion against the prospect\'s primary goal. Assess the value proposition (clarity, relevance, differentiation), list friction points with the evidence, and propose the 3-5 highest-leverage A/B tests. Score 0-100.',
} } };

const x = $json;
const pkg = { type: 'object', additionalProperties: false, required: ['name', 'monthly_price_usd', 'best_for', 'deliverables', 'expected_outcomes'],
  properties: { name: { type: 'string' }, monthly_price_usd: { type: 'integer' }, best_for: { type: 'string' },
    deliverables: { type: 'array', items: { type: 'string' } }, expected_outcomes: { type: 'array', items: { type: 'string' } } } };
const schema = { type: 'object', additionalProperties: false,
  required: ['headline', 'executive_summary', 'diagnosis', 'strategy_pillars', 'packages', 'recommended_package', 'first_90_days', 'roi_rationale', 'next_steps'],
  properties: { headline: { type: 'string' }, executive_summary: { type: 'string' }, diagnosis: { type: 'array', items: { type: 'string' } },
    strategy_pillars: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['title', 'why', 'what_we_do'],
      properties: { title: { type: 'string' }, why: { type: 'string' }, what_we_do: { type: 'string' } } } },
    packages: { type: 'array', items: pkg }, recommended_package: { type: 'string' },
    first_90_days: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['phase', 'focus', 'milestones'],
      properties: { phase: { type: 'string' }, focus: { type: 'string' }, milestones: { type: 'array', items: { type: 'string' } } } } },
    roi_rationale: { type: 'string' }, next_steps: { type: 'array', items: { type: 'string' } } } };
const { ai, ai_text, ai_error, ai_meta, ...rest } = x;
const cfg = $('Config').first().json;
return { json: { ...rest, cro: ai || { cro_score: null, value_prop_assessment: ai_error, friction_points: [], experiments: [] }, brain: {
  skill: 'sales-enablement', caller: 'Audit & Proposal', client: x.company, effort: 'high', max_tokens: 16000, schema,
  context: { agency: cfg.agency_name, company: x.company, website: x.website, goal: x.goal, monthly_budget_usd: x.budget, discovery_notes: x.notes, seo_audit: x.seo, cro_review: x.cro },
  task: `Write a deal-specific proposal from ${cfg.agency_name} to ${x.company}. Lead with their goal and the audit evidence, not our services. Give exactly 3 packages (good/better/best); the middle one must fit the stated budget of $${x.budget}/month and should be the recommended one. Each package lists concrete deliverables and realistic, non-guaranteed outcomes. The 90-day plan has three 30-day phases. Keep the ROI rationale honest and assumption-based.`,
} } };

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const li = (arr) => (arr || []).map((t) => `<li style="margin:0 0 6px">${esc(t)}</li>`).join('');
const card = (title, inner) => `<div style="border:1px solid #e5e7eb;border-radius:10px;padding:18px 20px;margin:0 0 16px"><h3 style="margin:0 0 10px;font-size:16px;color:#111827">${esc(title)}</h3>${inner}</div>`;
const shell = (title, sub, inner) => `<div style="font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;max-width:680px;margin:0 auto;color:#1f2937;line-height:1.5"><div style="padding:24px 0 8px"><div style="font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#6b7280">${esc(sub)}</div><h1 style="margin:4px 0 0;font-size:24px;color:#111827">${esc(title)}</h1></div>${inner}</div>`;
const pct = (v) => (v === null || v === undefined || Number.isNaN(v)) ? 'n/a' : `${v > 0 ? '+' : ''}${v.toFixed(1)}%`;

const x = $json; const p = x.ai || {}; const seo = x.seo || {}; const cro = x.cro || {};
const clamp = (v) => (v === null || v === undefined || v === '' ? null : Math.max(0, Math.min(100, Math.round(Number(v)))));
seo.seo_score = clamp(seo.seo_score); cro.cro_score = clamp(cro.cro_score);
const norm = (s) => String(s || '').trim().toLowerCase();
const recPkg = (p.packages || []).find((k) => norm(k.name) === norm(p.recommended_package)) || (p.packages || [])[1] || (p.packages || [])[0] || {};
p.recommended_package = recPkg.name || '';
const cfg = $('Config').first().json;
if (x.ai_error) {
  return { json: { ...x, subject: `[Needs attention] Proposal for ${x.company} failed`, html: `<p>The proposal step failed: ${esc(x.ai_error)}</p>` } };
}
const score = (label, v) => `<td style="padding:12px 16px;border:1px solid #e5e7eb;border-radius:8px;text-align:center"><div style="font-size:28px;font-weight:700;color:#111827">${v ?? '–'}</div><div style="font-size:12px;color:#6b7280">${label}</div></td>`;
const issues = (seo.critical_issues || []).map((i) => `<li style="margin:0 0 8px"><b>${esc(i.issue)}</b> <span style="font-size:12px;color:#b45309">[${esc(i.impact)}]</span><br><span style="color:#6b7280">${esc(i.evidence)}</span><br>→ ${esc(i.fix)}</li>`).join('');
const friction = (cro.friction_points || []).map((f) => `<li style="margin:0 0 8px"><b>${esc(f.issue)}</b><br><span style="color:#6b7280">${esc(f.evidence)}</span><br>→ ${esc(f.fix)}</li>`).join('');
const tests = (cro.experiments || []).map((t) => `<li style="margin:0 0 8px"><b>${esc(t.change)}</b>: ${esc(t.hypothesis)} <span style="color:#6b7280">(metric: ${esc(t.primary_metric)})</span></li>`).join('');
const pillars = (p.strategy_pillars || []).map((s) => `<li style="margin:0 0 8px"><b>${esc(s.title)}</b>: ${esc(s.why)}<br>${esc(s.what_we_do)}</li>`).join('');
const pkgs = (p.packages || []).map((k) => {
  const rec = k.name === p.recommended_package;
  return `<td valign="top" style="width:33%;padding:14px;border:${rec ? '2px solid #4f46e5' : '1px solid #e5e7eb'};border-radius:10px">${rec ? '<div style="font-size:11px;color:#4f46e5;font-weight:700">RECOMMENDED</div>' : ''}<div style="font-weight:700;font-size:15px">${esc(k.name)}</div><div style="font-size:22px;font-weight:700;margin:4px 0">$${Number(k.monthly_price_usd || 0).toLocaleString()}<span style="font-size:12px;color:#6b7280">/mo</span></div><div style="font-size:12px;color:#6b7280;margin-bottom:8px">${esc(k.best_for)}</div><ul style="padding-left:18px;font-size:13px">${li(k.deliverables)}</ul></td>`;
}).join('');
const roadmap = (p.first_90_days || []).map((ph) => `<li style="margin:0 0 8px"><b>${esc(ph.phase)}: ${esc(ph.focus)}</b><ul style="padding-left:18px">${li(ph.milestones)}</ul></li>`).join('');
const html = shell(p.headline || `Growth proposal for ${x.company}`, `${cfg.agency_name} · proposal draft for review`,
  `<table style="border-spacing:8px;margin:8px -8px 16px"><tr>${score('SEO score', seo.seo_score)}${score('CRO score', cro.cro_score)}${score('Budget / mo', '$' + Number(x.budget).toLocaleString())}</tr></table>`
  + card('Executive summary', `<p style="margin:0">${esc(p.executive_summary)}</p>`)
  + card('What we found', `<ul style="padding-left:18px;margin:0">${li(p.diagnosis)}</ul>`)
  + card('SEO: critical issues', `<ul style="padding-left:18px;margin:0">${issues}</ul><p style="margin:10px 0 0"><b>Quick wins:</b></p><ul style="padding-left:18px">${li(seo.quick_wins)}</ul>`)
  + card('Conversion review', `<p style="margin:0 0 8px">${esc(cro.value_prop_assessment)}</p><ul style="padding-left:18px;margin:0">${friction}</ul><p style="margin:10px 0 0"><b>First tests:</b></p><ul style="padding-left:18px">${tests}</ul>`)
  + card('Strategy', `<ul style="padding-left:18px;margin:0">${pillars}</ul>`)
  + `<table style="border-spacing:8px;margin:0 -8px 16px;width:100%"><tr>${pkgs}</tr></table>`
  + card('First 90 days', `<ul style="padding-left:18px;margin:0">${roadmap}</ul>`)
  + card('Why it pays back', `<p style="margin:0">${esc(p.roi_rationale)}</p>`)
  + card('Next steps', `<ol style="padding-left:18px;margin:0">${li(p.next_steps)}</ol>`)
  + `<p style="font-size:12px;color:#9ca3af">Generated by Agency OS from a homepage crawl and discovery notes. Review before sending to ${esc(x.contact_email || 'the prospect')}.</p>`);
return { json: { ...x, subject: `[Review] Proposal for ${x.company}: ${p.headline || ''}`.slice(0, 180), html, recommended_package: p.recommended_package, proposal_value_usd: recPkg.monthly_price_usd || '' } };

const x = $('Render Proposal Email').item.json;
return { json: { created_at: new Date().toISOString(), company: x.company, website: x.website, contact_name: x.contact_name,
  contact_email: x.contact_email, goal: x.goal, budget: x.budget, seo_score: x.seo?.seo_score ?? '', cro_score: x.cro?.cro_score ?? '',
  recommended_package: x.recommended_package, proposal_value_usd: x.proposal_value_usd, status: 'Draft sent to AM' } };
